import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void max_reduce_kernel(const float* input, float* output, int total_output_size,
                                  int non_reduce_size_0, int non_reduce_size_1,
                                  int non_reduce_stride_0, int non_reduce_stride_1,
                                  int step_reduce, int size_reduce) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output_size) return;

    int dim0_idx = idx / non_reduce_size_1;
    int dim1_idx = idx % non_reduce_size_1;

    int base_offset = dim0_idx * non_reduce_stride_0 + dim1_idx * non_reduce_stride_1;

    float max_val = -FLT_MAX;
    for (int k = 0; k < size_reduce; ++k) {
        int input_offset = base_offset + k * step_reduce;
        float val = input[input_offset];
        if (val > max_val) max_val = val;
    }

    output[idx] = max_val;
}

torch::Tensor max_reduce_cuda(torch::Tensor input, int dim, int total_output_size,
                              int non_reduce_size_0, int non_reduce_size_1,
                              int non_reduce_stride_0, int non_reduce_stride_1,
                              int step_reduce, int size_reduce) {
    auto output = torch::empty({total_output_size}, input.options());

    const int block_size = 256;
    int num_blocks = (total_output_size + block_size - 1) / block_size;

    max_reduce_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        total_output_size,
        non_reduce_size_0,
        non_reduce_size_1,
        non_reduce_stride_0,
        non_reduce_stride_1,
        step_reduce,
        size_reduce
    );

    auto output_sizes = input.sizes().vec();
    output_sizes.erase(output_sizes.begin() + dim);
    return output.reshape(output_sizes);
}
"""

max_reduce_cpp_source = """
torch::Tensor max_reduce_cuda(torch::Tensor input, int dim, int total_output_size,
                              int non_reduce_size_0, int non_reduce_size_1,
                              int non_reduce_stride_0, int non_reduce_stride_1,
                              int step_reduce, int size_reduce);
"""

max_reduce = load_inline(
    name='max_reduce',
    cpp_sources=max_reduce_cpp_source,
    cuda_sources=max_reduce_source,
    functions=['max_reduce_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.max_reduce = max_reduce

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        dim = self.dim
        input_size = x.size()
        output_size = list(input_size[:dim]) + list(input_size[dim+1:])

        non_reduce_sizes = output_size
        non_reduce_size_0 = non_reduce_sizes[0] if len(non_reduce_sizes) > 0 else 1
        non_reduce_size_1 = non_reduce_sizes[1] if len(non_reduce_sizes) > 1 else 1

        non_reduce_strides = [x.stride(i) for i in range(x.dim()) if i != dim]
        non_reduce_stride_0 = non_reduce_strides[0] if len(non_reduce_strides) > 0 else 0
        non_reduce_stride_1 = non_reduce_strides[1] if len(non_reduce_strides) > 1 else 0

        return self.max_reduce.max_reduce_cuda(
            x.contiguous(),
            dim,
            torch.Size(output_size).numel(),
            non_reduce_size_0,
            non_reduce_size_1,
            non_reduce_stride_0,
            non_reduce_stride_1,
            x.stride(dim),
            x.size(dim)
        )
